52	class ToolboxView extends ComponentView {
53	    static type = 'toolbox' as const;
54	
55	    _features: Dictionary<ToolboxFeature | UserDefinedToolboxFeature>;
56	
57	    _featureNames: string[];
58	
59	    render(
60	        toolboxModel: ToolboxModel,
61	        ecModel: GlobalModel,
62	        api: ExtensionAPI,
63	        payload: Payload & {
64	            newTitle?: ToolboxFeatureOption['title']
65	        }
66	    ) {
67	        const group = this.group;
68	        group.removeAll();
69	
70	        if (!toolboxModel.get('show')) {
71	            return;
72	        }
73	
74	        const itemSize = +toolboxModel.get('itemSize');
75	        const isVertical = toolboxModel.get('orient') === 'vertical';
76	        const featureOpts = toolboxModel.get('feature') || {};
77	        const features = this._features || (this._features = {});
78	
79	        const featureNames: string[] = [];
80	        zrUtil.each(featureOpts, function (opt, name) {
81	            featureNames.push(name);
82	        });
83	
84	        (new DataDiffer(this._featureNames || [], featureNames))
85	            .add(processFeature)
86	            .update(processFeature)
87	            .remove(zrUtil.curry(processFeature, null))
88	            .execute();
89	
90	        // Keep for diff.
91	        this._featureNames = featureNames;
92	
93	        function processFeature(newIndex: number, oldIndex?: number) {
94	            const featureName = featureNames[newIndex];
95	            const oldName = featureNames[oldIndex];
96	            const featureOpt = featureOpts[featureName];
97	            const featureModel = new Model(featureOpt, toolboxModel, toolboxModel.ecModel) as ToolboxFeatureModel;
98	            let feature: ToolboxFeature | UserDefinedToolboxFeature;
99	
100	            // FIX#11236, merge feature title from MagicType newOption. TODO: consider seriesIndex ?
101	            if (payload && payload.newTitle != null && payload.featureName === featureName) {
102	                featureOpt.title = payload.newTitle;
103	            }
104	
105	            if (featureName && !oldName) { // Create
106	                if (isUserFeatureName(featureName)) {
107	                    feature = {
108	                        onclick: featureModel.option.onclick,
109	                        featureName: featureName
110	                    } as UserDefinedToolboxFeature;
111	                }
112	                else {
113	                    const Feature = getFeature(featureName);
114	                    if (!Feature) {
115	                        return;
116	                    }
117	                    feature = new Feature();
118	                }
119	                features[featureName] = feature;
120	            }
121	            else {
122	                feature = features[oldName];
123	                // If feature does not exist.
124	                if (!feature) {
125	                    return;
126	                }
127	            }
128	            feature.uid = getUID('toolbox-feature');
129	            feature.model = featureModel;
130	            feature.ecModel = ecModel;
131	            feature.api = api;
132	
133	            const isToolboxFeature = feature instanceof ToolboxFeature;
134	            if (!featureName && oldName) {
135	                isToolboxFeature
136	                    && (feature as ToolboxFeature).dispose
137	                    && (feature as ToolboxFeature).dispose(ecModel, api);
138	                return;
