import { createChart, getECModel, getViewGroup } from '../../../core/utHelper';
import { EChartsType } from '../../../../../src/echarts';
import tokens from '../../../../../src/visual/tokens';
import Displayable from 'zrender/src/graphic/Displayable';
import { PathStyleProps } from 'zrender/src/graphic/Path';

describe('component/toolbox/emphasisColor', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    it('emphasis iconStyle borderColor should differ from the normal one', function () {
        chart.setOption({
            toolbox: {
                feature: {
                    saveAsImage: {},
                    restore: {}
                }
            },
            xAxis: {},
            yAxis: {},
            series: [{
                type: 'line',
                data: [1, 2, 3]
            }]
        });

        const toolboxModel = getECModel(chart).getComponent('toolbox');
        const normalBorderColor = toolboxModel.get(['iconStyle', 'borderColor'] as any);
        const emphasisBorderColor = toolboxModel.get(['emphasis', 'iconStyle', 'borderColor'] as any);

        expect(normalBorderColor).toEqual(tokens.color.accent50);
        expect(emphasisBorderColor).toEqual(tokens.color.accent70);
        expect(emphasisBorderColor).not.toEqual(normalBorderColor);
    });

    it('rendered toolbox icons should have a distinct stroke in the emphasis state', function () {
        chart.setOption({
            toolbox: {
                feature: {
                    saveAsImage: {},
                    restore: {}
                }
            },
            xAxis: {},
            yAxis: {},
            series: [{
                type: 'line',
                data: [1, 2, 3]
            }]
        });

        const toolboxGroup = getViewGroup(chart, 'toolbox');
        const iconPaths = toolboxGroup.children().filter(function (el) {
            return !!(el.states && el.states.emphasis);
        }) as Displayable[];

        expect(iconPaths.length).toBeGreaterThan(0);

        iconPaths.forEach(function (path) {
            const normalStroke = (path.style as PathStyleProps).stroke;
            const emphasisStroke = (path.states.emphasis.style as PathStyleProps).stroke;
            expect(normalStroke).toEqual(tokens.color.accent50);
            expect(emphasisStroke).toEqual(tokens.color.accent70);
            expect(emphasisStroke).not.toEqual(normalStroke);
        });
    });

});
```

Notes that make the second test valid against the real code:

* `createChart`, `getECModel` and `getViewGroup` are all real exports of
  `/workspace/test/ut/core/utHelper.ts` (lines 33, 141 and 152 respectively);
  `getViewGroup(chart, 'toolbox')` resolves the component view group via
  `chart._componentsMap[component.__viewId].group`.
* `utHelper` imports `../../../src/echarts.all`, so the toolbox component is registered.
* Only the icon paths get an `'emphasis'` state
  (`/workspace/src/component/toolbox/ToolboxView.ts:219`); the background `Rect` added by
  `listComponentHelper.makeBackground` (`/workspace/src/component/toolbox/ToolboxView.ts:321`,
  implementation `/workspace/src/component/helper/listComponent.ts:34-58`) has no states, so the
  `filter` above cleanly selects the icons.
* `ts-jest` is configured with `diagnostics: false`
  (`/workspace/test/ut/jest.config.cjs:39`), so the `as any` path-argument casts are only there
  for editor ergonomics.

---

## 4. Tests

A unit test is feasible and cheap — see Edit 2. Two levels are asserted:

1. **Model level** — `ToolboxModel` default option: `emphasis.iconStyle.borderColor` resolves to
   `tokens.color.accent70` and is not equal to `iconStyle.borderColor`. This directly encodes the
   yaml acceptance signal.
2. **Render level** — every rendered toolbox icon `Displayable` has
   `states.emphasis.style.stroke !== style.stroke`, which is what actually drives the pixel change
   when `enterEmphasis` / `api.enterEmphasis` runs.

The existing helper API was verified against `/workspace/test/ut/spec/component/dataZoom/helper.test.ts`,
which uses exactly `import { createChart, getECModel } from '../../../core/utHelper';` plus
`beforeEach(() => chart = createChart())` / `afterEach(() => chart.dispose())`.

Manual/visual verification: open `/workspace/test/toolbox-title.html` (or
`/workspace/test/toolbox-custom.html`) after `npm run dev` and hover the icons — the stroke must
visibly darken. `/workspace/test/dataZoom-toolbox.html` additionally exercises the
`setIconStatus(..., 'emphasis')` "active" path.

---

## 5. Verification

```bash
# Type check the source change
cd /workspace && npx tsc --noEmit -p tsconfig.json

# Lint the touched file
cd /workspace && npx eslint src/component/toolbox/ToolboxModel.ts

# Run the new spec only (no coverage, faster)
cd /workspace && npx jest --config test/ut/jest.config.cjs --coverage=false \
    -t "emphasis iconStyle borderColor should differ from the normal one"

# Or the whole new file
cd /workspace && npx jest --config test/ut/jest.config.cjs --coverage=false \
    test/ut/spec/component/toolbox/emphasisColor.test.ts

# Full unit-test suite (guards against a snapshot/expectation elsewhere pinning accent50)
cd /workspace && npm run test
```

Quick assertion without jest:

```bash
cd /workspace && grep -n -A 9 "iconStyle: {" src/component/toolbox/ToolboxModel.ts
# expect: iconStyle.borderColor = tokens.color.accent50
#         emphasis.iconStyle.borderColor = tokens.color.accent70
```

---

## 6. Risks / open questions

* **Dark mode is not improved by this change.** `/workspace/src/theme/dark.ts:100-104` overrides
  only `toolbox.iconStyle.borderColor` (with `tokens.darkColor.accent50`, HSL l ≈ 0.737) and leaves
  the emphasis to fall through to the light-mode default. After this change that default becomes
  `#404c76` (l ≈ 0.357) — a dark navy on a dark background, i.e. hover becomes *less* visible in
  dark mode than the pre-fix state (which was `#6578ba`). This was already broken before (the two
  colours were merely equal), and the upstream fix (apache/echarts PR #21384, commit
  `cc1815120e`, `fix(toolbox): fix default emphasis color`) touched **only**
  `src/component/toolbox/ToolboxModel.ts`. **Recommendation: keep Edit 1 as the scoped fix** and
  treat the dark theme as a separate change; the sibling requirement
  `/workspace/requirements/toolbox-dataview-darkmode.yaml` covers the toolbox dark-mode work.
  If a dark-mode-safe hover is wanted in the same patch, the minimal addition would be, at
  `/workspace/src/theme/dark.ts:100-104`, anchor:

  ```ts
    toolbox: {
        iconStyle: {
            borderColor: color.accent50
        }
    },
  ```

  replaced with:

  ```ts
    toolbox: {
        iconStyle: {
            borderColor: color.accent50
        },
        emphasis: {
            iconStyle: {
                borderColor: color.accent70
            }
        }
    },
  ```

  (`tokens.darkColor.accent70` has l ≈ 0.943, i.e. brighter than the dark `accent50` — correct
  direction for a dark background.) This is **optional / out of scope** for this requirement.

* **User themes that only override `toolbox.iconStyle`** (e.g. `/workspace/theme/dark.js:116`,
  `/workspace/theme/shine.js:69`, `/workspace/theme/macarons.js:84`, `/workspace/theme/infographic.js:78`,
  `/workspace/theme/dark-*.js:108`) will now hover to `accent70` instead of their own icon colour.
  That is the intended behaviour change (previously they hovered to `accent50`, which was already
  not their icon colour), and `/workspace/theme/v5.js:541-548` already sets both keys explicitly.

* **Choice of shade.** `accent70` is fixed by the upstream fix and matches
  `SliderTimelineModel`'s `controlStyle` (`accent50` → `emphasis accent70`). Any other shade
  (`accent60`, `accent80`) would satisfy the yaml literally but diverge from upstream; do not
  substitute.

* **`emphasis.iconStyle.color` stays unset**, so the icon fill remains `'none'` from the normal
  style — only the stroke changes on hover. That matches the screenshots in PR #21384 and needs
  no extra work.

* **Title text colour is derived from the emphasis style.** `/workspace/src/component/toolbox/ToolboxView.ts:266-270`
  does `fill: iconStyleEmphasisModel.get('textFill') || hoverStyle.fill || hoverStyle.stroke || tokens.color.neutral99`.
  Since `hoverStyle.fill` is undefined, the hover title text colour changes from `#6578ba` to
  `#404c76` as a side effect — darker and higher contrast on the default light background, so this
  is an improvement, but it is a visible diff in any toolbox screenshot test.

* **No existing unit test or snapshot pins `accent50` for the toolbox**
  (`grep -rn "accent" /workspace/test` returns nothing), so no test updates are forced.
